def M(tema, nivel):
  return {'materia': 'Matemática', 'tema': tema, 'nivel': nivel}


ARI, GRA, EST, EQU = 'Aritmética e Porcentagem', 'Grandezas e Medidas', 'Estatística', 'Equações e Sistemas'
